}

*{box-sizing:border-box}

.wrap{
  font-family:var(--sans);
  color:var(--ink);
  background:linear-gradient(180deg, #0b0d18, var(--bg));
  padding:18px;
  border:1px solid var(--line);
  border-radius:14px;
  max-width:980px;
  margin:0 auto;
}

.hdr{display:flex; gap:14px; align-items:flex-start; justify-content:space-between; margin-bottom:12px;}

h1{font-size:18px; margin:0 0 6px 0; letter-spacing:.2px}
h2{font-size:15px; margin:0 0 6px 0; color:var(--acc)}

.sub{margin:0; color:var(--muted); font-size:13px; line-height:1.35}

.panel{
  background:linear-gradient(180deg, var(--panel), var(--panel2));
  border:1px solid var(--line);
  border-radius:12px;
  padding:12px;
  margin:10px 0;
}

.row{display:flex; gap:10px; align-items:center; flex-wrap:wrap;}
.row.small{margin-top:8px}

label{font-size:12px; color:var(--muted); min-width:64px}

input[type="text"]{
  flex:1;
  min-width:240px;
  padding:10px 10px;
  border-radius:10px;
  border:1px solid var(--line);
  background:#0b0e1c;
  color:var(--ink);
  font-family:var(--mono);
  font-size:15px;
  outline:none;
}
input[type="text"]:focus{border-color:#3b4278; box-shadow:0 0 0 3px rgba(139,233,253,.08)}

