    ['μυχός','Acute on the final syllable','“The innermost place”; Herodian marks this example specially.'],
    ['μοιχός','Acute on the final syllable','Grouped with πτωχός and ἀρχός as adjectival forms.'],
    ['πτωχός','Acute on the final syllable','One of the adjectival forms explicitly said to be oxytone.'],
    ['δόλιχος','Acute on the antepenult','The pulse (ὄσπριον). Compare δολιχός “long”.'],
    ['δολιχός','Acute on the final syllable','“Long” (μακρός). Compare δόλιχος, the pulse.'],
    ['μοναχός','Acute on the final syllable','Explicitly oxytone in the passage; do not apply the longer -χος tendency mechanically.'],
    ['Ἀρρηχός','Acute on the final syllable','The Maeotian people, explicitly oxytone; Strabo, book 11.'],
    ['Καρδοῦχος','Circumflex on the penult','The people named in the passage, with Xenophon, Anabasis 3 (5, 15), and Sophainetus cited.'],
    ['Μόψος','Acute on the penult','A cited disyllable in -ψος under the non-adjectival barytone rule.'],
    ['γύψος','Acute on the penult','Another cited disyllable in -ψος under that rule.'],
    ['θάψος','Acute on the penult','A kind of wood; the passage also distinguishes Θάψος as a place-name.']
  ];
  const query = document.querySelector('#query');
  const results = document.querySelector('#results');
  const count = document.querySelector('#count');
  const key = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/σ/g,'ς');
  function render() {
    const selected = entries.filter(e => key(e[0]).includes(key(query.value)));
    results.replaceChildren();
    count.textContent = selected.length ? `${selected.length} cited ${selected.length === 1 ? 'form' : 'forms'}` : 'No matching cited example. Try δολιχος or Show all.';
    for (const [word,accent,note] of selected) {
      const card = document.createElement('article'); card.className = 'entry';
      const heading = document.createElement('h2'); heading.lang = 'grc'; heading.textContent = word;
      const rule = document.createElement('p'); rule.className = 'accent'; rule.textContent = accent;
      const explanation = document.createElement('p'); explanation.textContent = note;
      card.append(heading,rule,explanation); results.append(card);
    }
  }
  query.addEventListener('input',render);
  document.querySelector('#reset').addEventListener('click',() => {query.value='';render();query.focus();});
