(() => {
  const $ = s => document.querySelector(s);
  const inp=$('#inp'), full=$('#full'), poly=$('#poly'), strip=$('#strip');
  const plain=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  const key=s=>plain(s).toLowerCase().replace(/σ/g,'ς').trim();
  const clean=s=>s.normalize('NFC').replace(/\s+/g,' ').trim();
  const monotonic=s=>s.normalize('NFD').replace(/[\u0313\u0314\u0345]/g,'').replace(/\u0342/g,'\u0301').normalize('NFC');
  const display=s=>poly.checked?s:monotonic(s);
  const known=new Map();
  function add(words,rule) {
    for (const word of words) {
      const list=known.get(key(word))||[];
      list.push({word,rule});known.set(key(word),list);
    }
  }
  add(['ψευδής','πρηνής','ζαής','ἁλής','σαφής','πρυλής','φραδής','νωθής'],'Cited disyllabic adjective: acute, with genitive -ους and no syncope.');
  add(['πλήρης'],'Explicit exception: πλήρης, from πλειήρης; barytone means non-final accent here.');
  add(['Ἄρης'],'The proper name Ἄρης is cited with non-final accent.');
  add(['Μυῆς','Θυῆς','Κυῆς'],'Cited disyllabic proper name with υ in the penult: circumflex.');
  add(['Βρύης','Κύης','Γύης'],'Explicit exceptions: these are treated as trisyllabic and barytone, not circumflexed. Lowercase γύης is also distinguished as a land measure and plough part.');
  add(['Ἑρμῆς','Θαλῆς','Πυλῆς','Ποδῆς','Φαλῆς','Κισσῆς','Σωσῆς','Ἡρακλῆς','Σωκλῆς','Προκλῆς','Σοφοκλῆς','Ἀρτεμῆς','Ἀπελλῆς'],'Cited proper name from a fuller form: circumflex in the contracted form.');
  add(['ἀκραής','δυσαής','ὑπεραής'],'Cited compound with ἄω: acute.');
  add(['εὐκλεής','ἀκλεής','δυσκλεής'],'Adjective from κλέος: acute; the proper-name contraction must not be applied to these adjectives.');
  add(['τιμῆς','τεχνῆς','δαφνῆς','φθογγῆς','σθενῆς','λαχνῆς','ζαχρῆς','ἀργῆς'],'Cited form derived from -ηεις: circumflex.');
  const pairs=[['Ἡρακλέης','Ἡρακλῆς'],['Ἀρτεμέας','Ἀρτεμῆς'],['Θαλέας','Θαλῆς'],['Ἀπελλέας','Ἀπελλῆς']];
  for (const [word] of pairs) add([word],'Cited full proper-name form: non-final accent. Use the contractor to compare its contracted form.');
  function analyze() {
    const raw=clean(inp.value), options=known.get(key(raw))||[];
    const item=options.length===1?options[0]:options.find(x=>x.word.normalize('NFC').toLowerCase()===raw.toLowerCase());
    const ambiguous=!item && options.length>1;
    $('#norm').textContent=raw?(strip.checked?plain(raw):raw):'—';
    let output=item?display(item.word):ambiguous?options.map(x=>display(x.word)).join(' / '):raw;
    if(item && raw===raw.toUpperCase()) output=output.toUpperCase();
    if(item && raw[0]===raw[0].toLowerCase()) output=output[0].toLowerCase()+output.slice(1);
    $('#sugg').textContent=output||'—';
    $('#rule').textContent=raw?(item?item.rule:ambiguous?'Two cited accentuations with different syllabic treatment. Enter Κυῆς or Κύης to distinguish them; no single accent is inferred.':'Outside the cited examples: no accent inferred. Try an example below.'):'Type a cited example.';
  }
  function contract() {
    const raw=clean(full.value), pair=pairs.find(p=>key(p[0])===key(raw));
    let output=pair?display(pair[1]):raw;
    if(pair && raw===raw.toUpperCase()) output=output.toUpperCase();
    $('#contrOut').textContent=output||'—';
    $('#contrNote').textContent=!raw?'Type a cited fuller proper-name form.':pair?'Cited proper-name pair: '+display(pair[0])+' → '+display(pair[1])+'.':'No contraction applied: only the four cited proper-name pairs are supported.';
  }
  const examples=['ψευδής','πλήρης','Μυῆς','Βρύης','Κύης','Γύης','Ἡρακλέης','Ἡρακλῆς','εὐκλεής','δυσκλεής','τιμῆς'];
  for(const word of examples) {
    const b=document.createElement('button');b.type='button';b.className='chip';b.textContent=word;
    b.addEventListener('click',()=>{inp.value=word;analyze();});$('#chips').append(b);
  }
  $('#go').addEventListener('click',analyze);
  inp.addEventListener('keydown',e=>{if(e.key==='Enter')analyze();});
  $('#rand').addEventListener('click',()=>{inp.value=examples[Math.floor(Math.random()*examples.length)];analyze();});
  $('#contract').addEventListener('click',contract);
  full.addEventListener('keydown',e=>{if(e.key==='Enter')contract();});
  for(const control of [poly,strip]) control.addEventListener('change',()=>{analyze();contract();});
  $('#reset').addEventListener('click',()=>{inp.value='';full.value='';poly.checked=true;strip.checked=true;analyze();contract();inp.focus();});
  inp.value='ψευδης';analyze();contract();
})();

